const PLAN_TREES = [[/fan palm|washingtonia|date palm/i, ["fanpalm"], 1.1], [/palo verde/i, ["paloverde"], 1.05], [/ironwood/i, ["ironwood"], 1.05], [/cottonwood|sycamore/i, ["cottonwood", "mesquite"], 1.45], [/goodding willow|desert willow|willow/i, ["desertwillow"], 1.15], [/mesquite/i, ["mesquite"], 1.1], [/velvet ash|arizona ash/i, ["ash", "desertwillow"], 1.3], [/pecan|pomegranate|\bfig\b|apple|orchard/i, ["orchard", "desertwillow"], 1.0]];
