  const spread = [["mesquite", 380, 3, () => 0.8 + rnd() * 0.7, { wash: 1, off: 0.35, land: 0.08, city: 0.06 }], ["paloverde", 380, 3, () => 0.7 + rnd() * 0.8, { wash: 0.5, off: 1, land: 0.2, city: 0.08 }], ["saguaro", 640, 2, () => 0.6 + rnd() * 0.9, { wash: 0.2, off: 1, land: 0.18, city: 0.04 }],
    ["ocotillo", 300, 1, () => 0.7 + rnd() * 0.8, { wash: 0.2, off: 1, land: 0.22, city: 0.04 }], ["boulder", 140, 3, () => 0.5 + rnd() * 1.6, { wash: 1, off: 1, land: 0.15, city: 0.03 }], ["bush1", 3800, 0.3, () => 0.6 + rnd() * 1.1, { wash: 1, off: 0.9, land: 0.32, city: 0.12 }], ["bush2", 3000, 0.3, () => 0.6 + rnd() * 1.1, { wash: 1, off: 0.9, land: 0.32, city: 0.12 }]];
