// a one-off model with plain materials (the instanced sway shader needs instanceMatrix), one material per source map
const A2MATS = new Map(); function planPlainMats(g) { g.traverse((o) => { if (!o.isMesh || !o.material) return; const src = o.material; const key = src.map ? src.map.uuid : src.uuid; if (!A2MATS.has(key)) A2MATS.set(key, new THREE.MeshStandardMaterial({ map: src.map || null, color: src.map ? 0xffffff : (src.color ? src.color.getHex() : 0x6f7d4b), roughness: 0.9, side: THREE.DoubleSide, alphaTest: src.alphaTest || 0, transparent: false })); o.material = A2MATS.get(key); }); return g; }
function planBox(name, x, z, r) { const g = new THREE.Group(); g.name = name; g.userData.noCull = true; scene.add(g); A2.cull.push({ o: g, x, z, r }); return g; }
