// the Giveback Shop keeps its hangar on Hangar Lane, with the Impact Plaza totems either side of it
function planGivebackShop() {
  const rd = PLAN_IDX.road.get("hangar_ln"); const q = planPlace("giveback_shop"); const sx = q ? q.x : -190, sz = q ? q.z : 290;
  let best = null; if (rd) for (let i = 0; i < rd.pts.length - 1; i++) { const a = rd.pts[i], b = rd.pts[i + 1]; const vx = b[0] - a[0], vz = b[1] - a[1], L = Math.hypot(vx, vz); const t = Math.max(0, Math.min(L, ((sx - a[0]) * vx + (sz - a[1]) * vz) / L)); const px = a[0] + vx / L * t, pz = a[1] + vz / L * t; const d = Math.hypot(sx - px, sz - pz); if (!best || d < best.d) best = { d, px, pz, ux: vx / L, uz: vz / L }; }
  if (!best) return; let nx = best.uz, nz = -best.ux; if ((sx - best.px) * nx + (sz - best.pz) * nz < 0) { nx = -nx; nz = -nz; }   // the side of the lane the shop stands on
  const off = 4.5 + 3.5 + 12; const hx = best.px + nx * off, hz = best.pz + nz * off; const yaw = Math.atan2(-nx, -nz);   // the hangar door faces the lane
  const r = planPut("hangar", hx, hz, yaw, 1); if (r) { r.e.shop = "store"; const b = { id: "a2_giveback_shop", kind: "hangar", name: "Giveback Shop", x: hx, z: hz }; const rec = { id: b.id, b, kind: r.kind, scale: r.scale, yaw, e: r.e }; PLAN_BLD.push(rec); PLAN_IDX.bld.set(b.id, rec); }
  const hs = hotspots.find((h) => h.plan === "giveback_shop"); const fx = hx - nx * 14.5 + best.ux * 9, fz = hz - nz * 14.5 + best.uz * 9; if (hs) { hs.x = fx; hs.z = fz; hs.r = 8; hs.p = "The official Giveback store in its hangar on Hangar Lane (walk in and press E, or press E here): hats, tees, hoodies, the Sikk bikes and the $GBACK chain. The Impact Plaza totems either side of the door show the causes the giving reaches, every one of them recorded on chain."; }
  DEFER.push(() => { const causes = ["MEALS SERVED", "TREES PLANTED", "SCHOLARSHIPS", "CLEAN ENERGY", "SHELTER BUILT", "ANIMAL RESCUE"]; const corten = new THREE.MeshStandardMaterial({ color: 0x8a4a2a, roughness: 0.85, metalness: 0.25 }); const tb = planBox("impact plaza", hx, hz, 600); const scene = { add: (o) => tb.add(o) };
    for (let k = 0; k < 6; k++) { const side = k < 3 ? -1 : 1, j = k % 3; const x = hx - nx * (9 + j * 5) + best.ux * side * 18, z = hz - nz * (9 + j * 5) + best.uz * side * 18; if (!planSpotOK(x, z, 0.8)) continue; const y = getH(x, z); const g = new THREE.Group(); g.position.set(x, y, z); g.rotation.y = yaw + Math.PI; g.add(box(1.1, 4.2, 0.45, corten, 0, 2.1, 0));
      const tex = textTexture([{ text: causes[k], size: 78, y: 0.45, shadow: true }, { text: "ON-CHAIN VERIFIED · $GBACK", size: 40, y: 0.78, color: "#4DDE6F", font: "'Space Grotesk', system-ui, sans-serif", weight: 600 }], 1024, 384, { planks: false, border: "#4DDE6F" }); const bm = new THREE.Mesh(new THREE.PlaneGeometry(1.0, 0.38), new THREE.MeshStandardMaterial({ map: tex, roughness: 0.7, emissive: 0xffffff, emissiveMap: tex, emissiveIntensity: 0.35 })); bm.position.set(0, 3.0, 0.24); g.add(bm); g.add(box(0.06, 3.6, 0.06, new THREE.MeshStandardMaterial({ color: 0x4dde6f, emissive: 0x4dde6f, emissiveIntensity: 1.2 }), 0.62, 2.0, 0.1)); g.traverse((q) => { if (q.isMesh) q.castShadow = true; }); scene.add(g); addSolid(x, z, g.rotation.y, 1.1, 0.45, y, y + 4.2, "world"); } });
}
