  const wood = new THREE.MeshStandardMaterial({ map: TEX.wood, roughness: 0.9 }), dark = new THREE.MeshStandardMaterial({ color: 0x2a1f16, roughness: 0.9 }), steel = new THREE.MeshStandardMaterial({ color: 0x8a8f96, roughness: 0.4, metalness: 0.7 }), corten = new THREE.MeshStandardMaterial({ color: 0x8a4a2a, roughness: 0.85, metalness: 0.25 }), red = new THREE.MeshStandardMaterial({ color: 0xb8342a, roughness: 0.8 }), white = new THREE.MeshStandardMaterial({ color: 0xf1ece0, roughness: 0.8 });
