    for (let i = 0; i < 6; i++) { const lx = -8 + (i % 3) * 8, lz = -5 + Math.floor(i / 3) * 10; const t = new THREE.Group(); t.position.set(lx, 0, lz); t.add(box(2.2, 0.08, 0.9, wood, 0, 0.75, 0)); t.add(box(2.2, 0.06, 0.32, wood, 0, 0.46, 0.75)); t.add(box(2.2, 0.06, 0.32, wood, 0, 0.46, -0.75)); for (const sx of [-0.9, 0.9]) t.add(box(0.08, 0.75, 1.7, dark, sx, 0.38, 0)); t.add(box(0.06, 2.6, 0.06, steel, 0, 1.3, 0)); const um = new THREE.Mesh(new THREE.ConeGeometry(1.5, 0.6, 8, 1, true), new THREE.MeshStandardMaterial({ color: [0xb8342a, 0xf4cd5a, 0x4dde6f][i % 3], roughness: 0.9, side: THREE.DoubleSide })); um.position.y = 2.7; t.add(um); patio.add(t);
      for (const oz of [0.75, -0.75]) { const [sx, sz] = P(lx, lz + oz); const sdd = addSolid(sx, sz, yaw + Math.PI / 2, 2.2, 0.32, y0, y0 + 0.5, "world"); if (sdd) sdd.seat = true; } const [tx, tz] = P(lx, lz); addSolid(tx, tz, yaw + Math.PI / 2, 2.2, 0.9, y0 + 0.5, y0 + 0.8, "world"); }
    for (const fx of [-13, 13]) { const pit = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 0.9, 0.45, 16), new THREE.MeshStandardMaterial({ map: TEX.rock, color: 0xb8a68e, roughness: 0.95 })); pit.position.set(fx, 0.22, 0); patio.add(pit); const fire = new THREE.Mesh(new THREE.ConeGeometry(0.35, 0.8, 8), new THREE.MeshStandardMaterial({ color: 0xff7a1a, emissive: 0xff5a00, emissiveIntensity: 1.6, transparent: true, opacity: 0.85 })); fire.position.set(fx, 0.8, 0); patio.add(fire); const fl = new THREE.PointLight(0xff8a3a, 0.9, 12, 1.6); fl.position.set(fx, 1.2, 0); patio.add(fl); (SITES.fires = SITES.fires || []).push({ fire, fl }); }
    for (let k = 0; k < 3; k++) { const z0 = -9 + k * 9; const pts = []; for (let i = 0; i <= 8; i++) pts.push(new THREE.Vector3(-13 + i * 3.25, 3.6 - Math.sin(i / 8 * Math.PI) * 0.4, z0)); patio.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 16, 0.02, 4, false), new THREE.MeshStandardMaterial({ color: 0x222 }))); for (let i = 1; i < 8; i++) { const b = new THREE.Mesh(new THREE.SphereGeometry(0.09, 6, 5), new THREE.MeshStandardMaterial({ color: 0xffe08a, emissive: 0xffd35a, emissiveIntensity: 1.3 })); b.position.set(pts[i].x, pts[i].y - 0.15, z0); patio.add(b); } for (const sx of [-13, 13]) patio.add(box(0.12, 4, 0.12, steel, sx, 2, z0)); }
