  hotspots.push({ x: cx, z: cz, r: 24, t: "Rodeo arena", k: "The Corral · grandstands are open", p: "Take a seat in the stands. The bull runs the arena, the chutes and the stock pens are at the north end by the barn, and the Corral Saloon is across the way." });
  DEFER.push(() => { try { planFootings(RB); planMergeStatic(RB, planMergeKeep(RB), true); } catch (err) { console.warn("INT corral merge", err); } });   /* INT: posts reach the ground on the slope, then one mesh per material */
  { const [bx, bz] = F(-RX - 2, 0); hotspots.push({ x: bx, z: bz, r: 8, t: "Bull ride", k: "Minigame · eight seconds to glory", p: "Climb into the chute and ride. Press SPACE on every buck to keep your grip. Stay on for eight seconds and your time goes on the board.", play: "rodeo" }); }
