// ── transit: the Grand Loop shuttle round all three stages and the Flight Line Tug on the landside roads, with their stops and next-arrival boards ──
// a piece of a plan road or promenade from the projection of `from` to that of `to` (either direction); ["pts", [...]] passes points through
function planRoadPiece(id, from, to) {
  if (id === "pts") return from.map((q) => q.slice()); const r = PLAN_IDX.road.get(id) || PLAN_IDX.prom.get(id); if (!r) return []; const p = r.pts; const cum = [0]; for (let i = 1; i < p.length; i++) cum.push(cum[i - 1] + Math.hypot(p[i][0] - p[i - 1][0], p[i][1] - p[i - 1][1]));
  const proj = (q) => { let best = null; for (let i = 0; i < p.length - 1; i++) { const a = p[i], b = p[i + 1]; const vx = b[0] - a[0], vz = b[1] - a[1], L = Math.hypot(vx, vz) || 1e-6; const t = Math.max(0, Math.min(L, ((q[0] - a[0]) * vx + (q[1] - a[1]) * vz) / L)); const x = a[0] + vx / L * t, z = a[1] + vz / L * t; const d = Math.hypot(q[0] - x, q[1] - z); if (!best || d < best.d - 1e-6) best = { d, s: cum[i] + t, x, z }; } return best; };
  const A = proj(from), B = proj(to); if (!A || !B) return []; const out = [[A.x, A.z]];
  if (A.s <= B.s) { for (let i = 0; i < p.length; i++) if (cum[i] > A.s + 0.3 && cum[i] < B.s - 0.3) out.push(p[i].slice()); } else { for (let i = p.length - 1; i >= 0; i--) if (cum[i] < A.s - 0.3 && cum[i] > B.s + 0.3) out.push(p[i].slice()); }
  out.push([B.x, B.z]); return out; }
function planRoute(pieces) { const out = [], zones = []; let acc = 0; for (const [id, a, b, spd] of pieces) { const t0 = acc; for (const q of planRoadPiece(id, a, b)) { const l = out[out.length - 1]; if (l) { const d = Math.hypot(l[0] - q[0], l[1] - q[1]); if (d < 0.5) continue; acc += d; } out.push(q); } if (spd) zones.push([t0, acc, spd]); } return { pts: out, zones }; }
