  mmc.textAlign = "center"; for (const z of zoneRings) { if (PLAN_MODE && (!big || z.noLabel)) continue; const rr = (z.r / (T.xmax - T.xmin)) * S; const size = PLAN_MODE ? 9 : big ? 13 : 10; mmc.font = `700 ${size}px 'Space Grotesk', system-ui, sans-serif`; const name = (z.label || z.name).replace("The ", "").toUpperCase().split("").join(String.fromCharCode(8202)); const w = mmc.measureText(name).width + 10, h = size + 6; let x = px(z.center[0]) - w / 2, y = pz(z.center[1]) - rr + 4; if (!fits(x, y, w, h)) { y = pz(z.center[1]) + rr - h - 4; if (!fits(x, y, w, h)) continue; } boxes.push([x, y, w, h]); mmc.fillStyle = "rgba(10,22,16,.55)"; mmc.beginPath(); mmc.roundRect ? mmc.roundRect(x, y, w, h, 4) : mmc.rect(x, y, w, h); mmc.fill(); mmc.fillStyle = "#4DDE6F"; mmc.fillText(name, x + w / 2, y + h - 5); }
  if (!big) { const near = HUBS.map((h) => [h, Math.hypot(h[1] - player.position.x, h[2] - player.position.z)]).sort((a, b) => a[1] - b[1]).slice(0, 3); for (const [h] of near) { if (zoneRings.some((z) => z.name === h[0] || z.name === "The " + h[0])) continue; pill(h[0], px(h[1]), pz(h[2]), MAP_ICON[h[0]] || "#f5f1e6", 10); } return; }
