// ───────────────────────────── movement + net sync ─────────────────────────────
let lastSent = { x: 0, z: 48, ry: 0, at: 0 };
// what the local player is doing right now, so everyone else draws the same thing: seated in a cart, riding with someone, in a balloon, on the bull
function poseNow() { if (ARC.on) return "arcade"; if (FLY.on) return "flight"; if (cartMode && RIDEV.kind !== "cart") return "bike:" + RIDEV.bike; if (RIDE_ON.id) return "ride:" + RIDE_ON.id; if (SITES.bride) return "balloon:" + SITES.balloons.indexOf(SITES.bride.b); if (RIDE.on) return "bull"; if (SITES.ride) return "shuttle"; if (SITES.park) return "park"; if (SIT.on) return "sit"; if (DANCE.on) return "dance"; return null; }
function pushMove(force) { if (!player || riding) return; const now = performance.now(); { const mine = view && view.players[ME]; if (mine && !FLY.on && now - SYNC.at > 1500 && Math.hypot(mine.x - player.position.x, mine.z - player.position.z) > 120 && onLand(player.position.x, player.position.z)) { SYNC.at = now; act({ t: "warp", x: +player.position.x.toFixed(2), z: +player.position.z.toFixed(2) }); lastSent = { x: player.position.x, y: player.position.y, z: player.position.z, ry: yaw, at: now, pose: null }; return; } } const pose = poseNow(); const posed = !!pose && pose !== "dance"; const ry = posed ? player.rotation.y : yaw; const moved = Math.hypot(player.position.x - lastSent.x, player.position.z - lastSent.z) > 0.08 || Math.abs(ry - lastSent.ry) > 0.02 || Math.abs(player.position.y - (lastSent.y || 0)) > 0.15 || pose !== lastSent.pose; if (force || (moved && now - lastSent.at > 120) || now - lastSent.at > 3000) { act({ t: "move", x: +player.position.x.toFixed(2), y: +player.position.y.toFixed(2), z: +player.position.z.toFixed(2), ry: +ry.toFixed(3), cart: cartMode, pose }); lastSent = { x: player.position.x, y: player.position.y, z: player.position.z, ry, at: now, pose }; } }
let CREATOR_A = 0; let lastT = performance.now(), bob = 0, bobY = 0; const camTarget = new THREE.Vector3(); const CAM = { dist: 9.5, look: new THREE.Vector3(), init: false, prAcc: 0, prN: 0, pr: 0 };
const smoothK = (dt, rate) => 1 - Math.exp(-dt * rate);
function toggleFpv(on) { FPV = on === undefined ? !FPV : !!on; const b = $("#fpvbtn"); if (b) b.textContent = FPV ? "VIEW 1ST" : "VIEW 3RD"; if (player && player.userData.walk && !FPV) player.userData.walk.visible = true; if (player && player.userData.label) player.userData.label.visible = !FPV; sfx("ui"); }
