  if (!u.fpvHead || !(Math.abs(eye.x - p.x) < 1.2 && Math.abs(eye.z - p.z) < 1.2 && eye.y > p.y + 0.3 && eye.y < p.y + 2.6)) eye.set(p.x, p.y + 1.62, p.z);
