// ───────────────────────────── the fly-in tutorial ─────────────────────────────
const TUT = { on: false, step: 0, cardAt: 0, card: 0 };
const QUEST = { steps: [["Find Sky at the tour booth", "She is right outside arrivals, by the parked carts. Walk up and press E."], ["Ride the site shuttle", "Green carts run the boulevard and stop at every hub. Press F beside one."], ["Visit the Giveback Shop", "Follow the signposts to the Impact Plaza and press E at the store."], ["Take a seat somewhere", "Any bench, stool or chair on the site. Press E next to it."], ["Watch the sunset from a balloon", "Out at the Balloon Field. Press E at a basket."]], i: +(localStorage.getItem("g1:quest") || 0), shown: 0 };
function questAdvance(step) { if (QUEST.i !== step) return; QUEST.i++; localStorage.setItem("g1:quest", String(QUEST.i)); sfx("buy"); try { act({ t: "quest", step }); } catch (e) {} setStatus("+25 GB · day one step " + (step + 1) + " done"); if (QUEST.i >= QUEST.steps.length) { setStatus("Day one complete. Genesis One is yours to explore."); showTut("Day one complete", "You found Sky, rode the shuttle, saw the shop, sat a while and flew. Everything else is out there. Press M any time for the tower view."); setTimeout(() => $("#tut").classList.remove("on"), 9000); } else questShow(); }
