buildWorld().then(() => { const lk = savedLook(); player = avatar(ME, localStorage.getItem("g1:name") || "You", lk, null, null); player.position.set(TERM.exit[0], getH(TERM.exit[0], TERM.exit[1]), TERM.exit[1]); yaw = TERM.exitYaw !== undefined ? TERM.exitYaw : TERM.rot + Math.PI; player.rotation.y = yaw + Math.PI; if (!localStorage.getItem("g1:flown")) { setLoad(0.98, "Preparing Giveback One for your arrival"); warmCabin(); } $("#load").classList.add("off"); askName(); connect(); CAM.snap = 2; try { updateSky(0); updateEnvironment(performance.now(), true); } catch (e) { console.warn("first-frame lighting", e); } frame(); if (!localStorage.getItem("g1:tut") && localStorage.getItem("g1:flown") && PLACE.terminal && MODELS.terminal) setTimeout(() => { const e = PLACE.terminal[0]; enterInterior({ kind: "terminal", i: 0, e, r: MODELS.terminal.radius * e[4] }); if (inside) { const lx = -inside.half + 16, lz = -inside.half + 12; player.position.set(e[0] + lx * Math.cos(e[3]) + lz * Math.sin(e[3]), e[1] + 0.05, e[2] - lx * Math.sin(e[3]) + lz * Math.cos(e[3])); yaw = e[3] + Math.PI; player.rotation.y = e[3]; camera.position.copy(player.position).add(new THREE.Vector3(Math.sin(e[3]) * 3, 2, Math.cos(e[3]) * 3)); } }, 600); }).catch((err) => { setStatus("failed to load the site: " + err.message, true); console.error(err); });
